 const [preparedBy,setPreparedBy]=useState('Ceylon Wellness');
 const [finalNote,setFinalNote]=useState('');const [journeySubmitted,setJourneySubmitted]=useState(false);const [journeySending,setJourneySending]=useState(false);const [websiteTrap,setWebsiteTrap]=useState('');const [contactName,setContactName]=useState('');const [contactEmail,setContactEmail]=useState('');const [contactPhone,setContactPhone]=useState('');const [delivery,setDelivery]=useState('Email + WhatsApp');const [privacyOk,setPrivacyOk]=useState(false);const toggle=(x:string)=>setInterests(interests.includes(x)?interests.filter(i=>i!==x):[...interests,x]);const toggleFeel=(x:string)=>setSelectedFeels(prev=>{const next=prev.includes(x)?prev.filter(i=>i!==x):[...prev,x];setFeel(next[0]||'');return next});const toggleDestination=(x:string)=>setDestinations(prev=>prev.includes(x)?prev.filter(i=>i!==x):[...prev,x]);const questions=[v.wellness,c.interestQ,'Where would you love to experience Sri Lanka?',v.dates,v.travellers,v.stay,v.budget,'Anything special?'];const complete=[selectedFeels.length>0,interests.length>0,destinations.length>0,(!!durationRange||flexible|| (!!arrival&&!!departure&&departure>arrival)),!!party&&adults>0&&!(party==='Family'&&children<1),!!stay,true,true];const chosenDays=durationRange==='5â€“7 days'?7:durationRange==='8â€“10 days'?10:durationRange==='11â€“14 days'?14:durationRange==='15+ days'?15:(nights||7);const result=routeIdea(chosenDays,interests,pace);const generated=makeDayPlan(chosenDays,interests,pace,feel);const plan=editedPlan||generated;const reset=()=>{setStep(0);setArrival('');setDeparture('');setFlexible(false);setFlight('');setLanding('');setPickup('');setParty('');setAdults(1);setChildren(0);setAges('');setFeel('');setSelectedFeels([]);setDestinations([]);setDurationRange('');setStay('');setInterests([]);setTransport('Recommend for me');setBudget('Not sure yet');setBudgetAmount('');setQuoteCurrency('EUR');setPersonaliseMore(false);setPace('Balanced');setNotes('');setEditedPlan(null);setResultSlide(0)};const dateLine=flexible