 const localizedResult=routeIdea(nights||7,interests,pace,lang);const visiblePlan=plan.map(day=>localizeDayPlan(day,lang));const displayDateLine=flexible?v4Labels[lang].flexibleDates:`${arrival} â†’ ${departure}${nights?` (${nights} ${v.nights})`:''}`;
 const planText=plan.map(day=>{const localized=localizeDayPlan(day,preferredLanguage);return `${v4Labels[preferredLanguage].dayLabel} ${day.day} â€” ${localized.place}: ${localized.focus}. ${localized.activity}`;}).join('\n');
 const cc=contactCopy[lang];const emailValid=/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(contactEmail);const contactReady=!!contactName.trim()&&emailValid&&!!contactPhone.trim()&&privacyOk;
