 const confirmSoftDelete=async()=>{if(!supabase||!deleteModal||deleteModal.mode!=='soft')return;const target={...deleteModal};const table=target.kind==='travel'?'leads':'reiki_requests';const deletedAt=new Date().toISOString();setNotice('Moving journey to Trashâ€¦');const {data,error}=await supabase.from(table).update({deleted_at:deletedAt,deleted_reason:'Moved to Trash by admin',updated_at:deletedAt}).eq('id',target.id).select('id,deleted_at').maybeSingle();if(error||!data?.deleted_at){console.error('Move to Trash failed',error);setNotice(`Could not move record to Trash${error?.message?`: ${error.message}`:'. Please check Supabase update permissions.'}`);return;}try{await audit('TRASH',target.kind==='travel'?'lead':'reiki_request',target.id,{reason:'Moved to Trash by admin'});}catch(auditError){console.error('Trash audit failed',auditError);}setDeleteModal(null);setEditing(false);if(target.kind==='travel')setSelected(null);else setSelectedReiki(null);await load();setNotice('Journey moved to Trash. Open Trash to restore it.');};
