 const parseAgentRequest=()=>{if(!draft||!agentPaste.trim())return;const text=agentPaste.replace(/\r/g,' ');const lower=text.toLowerCase();const next={...draft};const people=text.match(/\b(\d{1,2})\s*(?:adults?|persons?|people|pax|travellers?|travelers?)\b/i);if(people)next.travellers=Math.max(1,Number(people[1]));const nights=text.match(/\b(\d{1,2})\s*(?:nights?|nts?)\b/i);const days=text.match(/\b(\d{1,2})\s*days?\b/i);if(nights)next.duration=`${Number(nights[1])+1} days / ${nights[1]} nights`;else if(days)next.duration=`${days[1]} days`;const currencyMatch=text.match(/\b(EUR|USD|GBP|PLN|LKR|CHF|AUD|CAD)\s*([0-9][0-9,. ]*)|(?:â‚¬|Â£|\$)\s*([0-9][0-9,. ]*)/i);if(currencyMatch){let cur=(currencyMatch[1]||({'â‚¬':'EUR','Â£':'GBP','$':'USD'}[text.match(/[â‚¬Â£$]/)?.[0]||'']||draft.currency||'EUR')).toUpperCase();let raw=(currencyMatch[2]||currencyMatch[3]||'').replace(/\s/g,'').replace(/,(?=\d{3}\b)/g,'');next.currency=cur;next.budget_range=`${cur} ${raw}`;}const hotel=text.match(/\b([345])\s*\*?\s*(?:star|stars|â˜…)/i);if(hotel)next.accommodation=`${hotel[1]}â˜… comfort`;const airport=text.match(/\b(CMB|BIA|Bandaranaike|Colombo airport)\b/i);if(airport)next.arrival_airport='CMB Â· Bandaranaike International Airport';const interestMap=[['ayurveda','Ayurveda'],['yoga','Yoga'],['meditation','Meditation'],['nature','Nature'],['wildlife','Wildlife'],['culture','Culture'],['beach','Beach'],['ocean','Beach'],['spiritual','Spirituality'],['reiki','Reiki'],['tea','Tea Country']];const found=interestMap.filter(([k])=>lower.includes(k)).map(([,v])=>v);if(found.length)next.wellness_interests=Array.from(new Set([...(next.wellness_interests||[]),...found]));const dateLine=text.match(/(?:arrival|arrive|from|date)\s*[:\-]?\s*([^\n,;]{4,28})/i);if(dateLine&&!next.travel_dates)next.travel_dates=dateLine[1].trim();setDraft(next);setNotice('Agent request parsed. Please check the highlighted traveller facts before building the route.');};
