 const buildRouteDraft=()=>{if(!draft)return;const days=journeyDays();const interests=(draft.wellness_interests||[]).join(' ').toLowerCase();let route:string[]=[];if(days<=7)route=['Negombo','Sigiriya','Kandy','South Coast'];else if(days<=10)route=['Negombo','Sigiriya','Kandy','Ella','South Coast'];else route=['Negombo','Sigiriya','Kandy','Nuwara Eliya','Ella','Yala / Tissamaharama','South Coast'];if(interests.includes('ayurveda')||interests.includes('wellness'))route[route.length-1]='South Coast Â· Wellness stay';if(interests.includes('wildlife')&&days>7&&!route.some(x=>x.includes('Yala')))route.splice(route.length-1,0,'Yala / Tissamaharama');const base=Math.floor(days/route.length),extra=days%route.length;let day=1;const list:DayPlan[]=[];route.forEach((place,i)=>{const span=Math.max(1,base+(i<extra?1:0));for(let n=0;n<span;n++){list.push({day:day++,place,focus:n===0?'Arrival, settle & local rhythm':'Wellness + discovery',activity:'',stay:place,notes:''});}});setDraft({...draft,itinerary:list.slice(0,days)});setNotice('Route draft created from journey length and interests. Adjust cities and days before pricing.');};
